window.STORY_LIBRARY.push(...[{"id": "yuyu-friends-v1", "title": "我的好朋友", "overview": "第1–6頁第一天；第7–19頁第二天；第20頁第三天。湘湘的辮子、瑜瑜制服及書包沿用第一本參考圖。\n20 頁正文，封面另計。正文文字可獨立編輯與拖曳。A 版封面的書名已印在圖片上；另保留無字封面。原圖尺寸 1448×1086。", "pageSize": "2048x1536", "coverAssets": {"clean": {"id": "friends-f53921f3a39f515727c52d179e0725d41dc38b7231c19a0fed5137158c42b36d", "name": "cover.png", "asset": "stories/saved/images/f53921f3a39f515727c52d179e0725d41dc38b7231c19a0fed5137158c42b36d.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2262637}, "selected": {"id": "friends-3c53436725ad7fdd5ce27339dd55faad63aa167c19027a8978f2351302ceeb78", "name": "cover-titled-A.png", "asset": "stories/saved/images/3c53436725ad7fdd5ce27339dd55faad63aa167c19027a8978f2351302ceeb78.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2334475}}, "pages": [{"id": "yuyu-friends-v1-cover", "title": "封面", "text": "", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 86.9, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": false, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-3c53436725ad7fdd5ce27339dd55faad63aa167c19027a8978f2351302ceeb78", "name": "cover-titled-A.png", "asset": "stories/saved/images/3c53436725ad7fdd5ce27339dd55faad63aa167c19027a8978f2351302ceeb78.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2334475}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-1", "title": "每天一起進教室", "text": "每天早上，瑜瑜都會在校門口找一找。\n看見湘湘的辮子，她就笑了。\n「等我一下！」\n兩個人揹著書包，一起走進教室。", "scene": "校門中遠景；瑜瑜星形髮夾、湘湘雙辮子，沿用第一本制服書包。相互等待，不奔跑穿車道。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-1e0dd260c131ae2e7d3fa1914f2784204d37f3cb20db89c997831af2cdb327c8", "name": "page01.png", "asset": "stories/saved/images/1e0dd260c131ae2e7d3fa1914f2784204d37f3cb20db89c997831af2cdb327c8.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2554958}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-2", "title": "一起放書包", "text": "「水壺放好了嗎？」湘湘問。\n「放好了！你的聯絡簿呢？」瑜瑜也問。\n書包掛好，桌面排整齊。\n有朋友提醒，早晨好像更容易開始。", "scene": "教室雙人中景，分開整理各自桌面；清楚兩雙手，物件不重疊。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-d90253bf47f4a09537e2dc9dce36c684ef91d83ba8acd92fb9574bf7b599a65f", "name": "page02.png", "asset": "stories/saved/images/d90253bf47f4a09537e2dc9dce36c684ef91d83ba8acd92fb9574bf7b599a65f.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2259265}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-3", "title": "一起上課", "text": "老師問了一個問題，湘湘舉起手。\n瑜瑜坐得直直的，偷偷替她加油。\n湘湘說完答案，轉頭看了看她。\n瑜瑜回了一個小小的笑。", "scene": "湘湘舉一手、另一手桌上；瑜瑜側面看她微笑。老师遠景不搶焦點。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-28046d4a74a7926b66e856219eebbc6de80f19db3d68839898b6b6e7a89424ef", "name": "page03.png", "asset": "stories/saved/images/28046d4a74a7926b66e856219eebbc6de80f19db3d68839898b6b6e7a89424ef.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2052269}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-4", "title": "一起借文具", "text": "瑜瑜畫錯了一條線，卻找不到橡皮擦。\n湘湘把自己的推過來。\n「借你。」\n「謝謝，我用完就還你。」\n一塊小小的橡皮擦，在兩張桌子之間走了一趟。", "scene": "桌面近景，橡皮擦放桌上推給對方，避免空中交疊的手。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-76ed1667b9ac3ef3a1c4c0f01cb86b5e14fe21226eaaee89f8c34fe80ee99eda", "name": "page04.png", "asset": "stories/saved/images/76ed1667b9ac3ef3a1c4c0f01cb86b5e14fe21226eaaee89f8c34fe80ee99eda.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2128901}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-5", "title": "一起下課", "text": "下課了，兩人走到遊戲區。\n「這次換你先跳！」\n瑜瑜跳進格子，湘湘在旁邊數。\n笑聲一格一格，跳進了陽光裡。", "scene": "戶外地面跳格子；一人跳一人站旁，無高處危險，格子不印文字。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-6a0ae95b5db0189bc93bf5569436145f9c10d91b662c0e2d98b6857757883fbd", "name": "page05.png", "asset": "stories/saved/images/6a0ae95b5db0189bc93bf5569436145f9c10d91b662c0e2d98b6857757883fbd.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2632598}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-6", "title": "一起吃午餐", "text": "午餐時，兩人坐在附近。\n「今天的南瓜甜甜的。」瑜瑜說。\n「我喜歡這個青菜！」湘湘說。\n她們聊著各自喜歡的菜，也記得把自己的午餐好好吃完。", "scene": "第一天午餐中景，各自餐盤與湯匙，不互換食物；開心聊天。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-f621fe1b009eab5a8a3f6a275dd4ec028926c677cd7aba1209cb0b076eaee3a5", "name": "page06.png", "asset": "stories/saved/images/f621fe1b009eab5a8a3f6a275dd4ec028926c677cd7aba1209cb0b076eaee3a5.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2102497}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-7", "title": "一起完成作品", "text": "隔天上午，美術課要兩人合作畫一張大圖。\n瑜瑜畫天空，湘湘畫花草。\n「這裡還有好多空白呢！」\n她們把彩色筆排開，想把畫紙變成一座小花園。", "scene": "第二天上午起。俯視同一張橫向紙，天空淡藍、下方花草，中央留白；彩虹大樹尚未畫。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-2853c6dc1b68421e6966aba5e74a3c6d1c85c843c1031d24d20c0ae50f44b4fc", "name": "page07.png", "asset": "stories/saved/images/2853c6dc1b68421e6966aba5e74a3c6d1c85c843c1031d24d20c0ae50f44b4fc.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2562884}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-8", "title": "小小的不同意", "text": "瑜瑜拿起彩色筆。\n「這裡畫彩虹！」\n湘湘指著同一塊空白。\n「可是，我想畫一棵大樹。」\n兩根手指停在紙上，誰也沒有先移開。", "scene": "兩人各指空白區、表情堅持，手臂分開；同一張未完成畫。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-61e3be51f7d682cffc9a4b356bdd8ddd85dac453da67df1c08aacf3f1ba326f5", "name": "page08.png", "asset": "stories/saved/images/61e3be51f7d682cffc9a4b356bdd8ddd85dac453da67df1c08aacf3f1ba326f5.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2433018}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-9", "title": "一句話說重了", "text": "「這樣不好看啦！」瑜瑜急急地說。\n湘湘的手停住了。\n「可是……」她只說了兩個字，就把筆放下。\n剛才熱鬧的小花園，忽然安靜了。", "scene": "中近景情緒轉折。瑜瑜著急而非惡意怒吼，湘湘受傷抿嘴；不加羞辱符號。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-a3de8d1d0bf2fc875cb88c8c9cccfb0cdb8b05f59b124eb3177fce349ed25359", "name": "page09.png", "asset": "stories/saved/images/a3de8d1d0bf2fc875cb88c8c9cccfb0cdb8b05f59b124eb3177fce349ed25359.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2312348}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-10", "title": "誰也不說話", "text": "下課時，湘湘先走到走廊。\n瑜瑜留在窗邊，沒有叫住她。\n她們都想偷偷看一眼，卻又把頭轉開。\n明明沒有走多遠，今天的距離卻好長。", "scene": "窗內外同框，兩人仍在老師可照看的教室走廊區，安全窗戶不攀爬。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-710cc9097205a1bfbca14c8d6eeadc8ca5f69dbc7439757bba8b4a49a333deeb", "name": "page10.png", "asset": "stories/saved/images/710cc9097205a1bfbca14c8d6eeadc8ca5f69dbc7439757bba8b4a49a333deeb.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2361660}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-11", "title": "午餐也安靜了", "text": "到了午餐時間，兩人沒有坐在附近。\n瑜瑜看見湘湘低頭吃飯，又趕快移開眼睛。\n今天也有喜歡的菜。\n可是她最想說的那句話，一直沒有說出口。", "scene": "第二天午餐，兩人在同教室不同座位；不是同一天第二頓午餐，不誇張孤立霸凌。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-9e1df879dba1195843cf690a46a2ad60aead96a6dfdd086fa22cb1277c59e9a0", "name": "page11.png", "asset": "stories/saved/images/9e1df879dba1195843cf690a46a2ad60aead96a6dfdd086fa22cb1277c59e9a0.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2228280}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-12", "title": "其實我也不開心", "text": "午休前，瑜瑜看見她們以前一起做的小書籤。\n那時，她們笑得多開心呀。\n「我還在生氣嗎？」她想。\n心裡酸酸的，好像更是難過。\n她想念和湘湘一起玩的時候。", "scene": "瑜瑜安靜看雙人花草書籤近景，既有作業不是本次未完成大畫。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-6197c34765e48dad846ac7eacce55106a05fbb404ea7a35fa70980162f24b22b", "name": "page12.png", "asset": "stories/saved/images/6197c34765e48dad846ac7eacce55106a05fbb404ea7a35fa70980162f24b22b.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2101652}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-13", "title": "老師先聽一聽", "text": "老師注意到她們今天很安靜。\n她沒有急著說誰對、誰錯。\n「你最希望湘湘知道什麼？」她問瑜瑜。\n等瑜瑜說完，老師也去聽湘湘的想法。", "scene": "只畫一個時刻：老師蹲下聽瑜瑜說，湘湘安全背景。不可同格複製老師。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-0818ae4d0d925bd29721033cffbc5055116e2e9e257272f8b33833599e477601", "name": "page13.png", "asset": "stories/saved/images/0818ae4d0d925bd29721033cffbc5055116e2e9e257272f8b33833599e477601.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2384566}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-14", "title": "原來她也有想法", "text": "後來，她們一起看著那張畫。\n湘湘小聲說：「我不是不要彩虹。我昨天看到一棵好大的樹，很想畫下來。」\n瑜瑜愣了一下。\n原來，湘湘也有一個想放進畫裡的故事。", "scene": "兩女孩桌旁老師居中偏後傾聽，湘湘解釋，瑜瑜放鬆；樹尚未完成。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-c17c6bb9a4ce9f870b67dbc05c448327e67f4c7818405a61d7b1efe3848fd40d", "name": "page14.png", "asset": "stories/saved/images/c17c6bb9a4ce9f870b67dbc05c448327e67f4c7818405a61d7b1efe3848fd40d.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2199899}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-15", "title": "要不要先說對不起", "text": "瑜瑜拿起未完成的畫，走到湘湘身邊。\n「我可以坐這裡嗎？」\n湘湘輕輕點頭。\n瑜瑜吸了一口氣。\n這一次，她想慢慢把話說清楚。", "scene": "瑜瑜雙手拿畫靠近，湘湘坐著點頭；紙面方向和前頁一致，不畫成完成作品。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-edd70cac99b0db98abdac1a2b4b8cb598f3518f822a77c8bc5ba8d791cf6d358", "name": "page15.png", "asset": "stories/saved/images/edd70cac99b0db98abdac1a2b4b8cb598f3518f822a77c8bc5ba8d791cf6d358.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2302945}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-16", "title": "我剛剛說得太兇了", "text": "「我剛剛說得太兇了，對不起。」瑜瑜說。\n「我只是很想畫彩虹，沒有先聽你說。」\n湘湘也低聲說：「我後來故意不理你。其實，我很難過。」\n她們終於看著彼此，把心裡的話說了出來。", "scene": "平視雙人特寫，歉意、坦誠，不強迫擁抱或突然大笑；手放桌上。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-43ff7af800c462d4a991e7a61652d6b39513be48de5c4b63660531fcc5dd98c3", "name": "page16.png", "asset": "stories/saved/images/43ff7af800c462d4a991e7a61652d6b39513be48de5c4b63660531fcc5dd98c3.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2246824}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-17", "title": "一起把畫完成", "text": "「大樹放左邊，彩虹放右邊，好不好？」瑜瑜問。\n「好！樹下面還可以有兩個小朋友。」湘湘說。\n她們重新拿起筆。\n這一次，一邊畫，也一邊問問對方。", "scene": "俯視作品進行中，畫面左樹右彩虹、底部兩小朋友；兩人各用一支筆。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-2e9306e25c80d04396bf96271c1cddc4f1341e8ffaf0dfb945fb6f23c4dbe079", "name": "page17.png", "asset": "stories/saved/images/2e9306e25c80d04396bf96271c1cddc4f1341e8ffaf0dfb945fb6f23c4dbe079.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2574521}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-18", "title": "兩個人的小花園", "text": "畫完成了。\n左邊的大樹張開枝葉，右邊的彩虹彎彎的。\n樹下，兩個小朋友站在一起。\n「這是我們的小花園！」\n兩個人的想法，都有了自己的位置。", "scene": "兩人舉完成作品展示，畫上左樹右彩虹布局鎖定；笑容自然。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-53ed576a2df18016802acef8d82a8b124826826cad6d739b57b17e76b2e89735", "name": "page18.png", "asset": "stories/saved/images/53ed576a2df18016802acef8d82a8b124826826cad6d739b57b17e76b2e89735.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2401959}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-19", "title": "放學一起走", "text": "放學了，瑜瑜和湘湘一起走向校門。\n「明天還一起跳格子嗎？」\n「好呀，換你先跳。」\n她們看見等候的家長，揮揮手。\n今天，她們又走回了彼此身邊。", "scene": "夕陽校門安全接送區，兩女孩並肩；瑜瑜媽媽遠景接送，保持第一本造型。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-f492a7e78f42d2a0c9f62b51ae5c2e6090148926d8038bc6ca0068ae29ea8bbc", "name": "page19.png", "asset": "stories/saved/images/f492a7e78f42d2a0c9f62b51ae5c2e6090148926d8038bc6ca0068ae29ea8bbc.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2517586}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-friends-v1-page-20", "title": "再牽回彼此的手", "text": "隔天早上，她們又在校門口碰面。\n「早安！」\n好朋友不是永遠都不生氣。\n是生氣以後，還願意說一說、聽一聽，\n再牽回彼此的手。", "scene": "與第1頁呼應晨光，兩人輕牽手步入校園；只一組接觸手，清楚解剖。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "friends-ea6871cb900260529cce009ca6386fdbfa24b0003d391cbc5b7b688b5b6800cc", "name": "page20.png", "asset": "stories/saved/images/ea6871cb900260529cce009ca6386fdbfa24b0003d391cbc5b7b688b5b6800cc.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2606711}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}]}, {"id": "yuyu-after-school-v1", "title": "放學以後", "overview": "第1–10頁放學購物；第11頁回家冷藏食材；第12–17頁媽媽陪伴公園探索；第18–20頁到家分享與睡前收尾。第12頁起無書包與購物袋，第20頁換睡衣。\n20 頁正文，封面另計。正文文字可獨立編輯與拖曳。A 版封面的書名已印在圖片上；另保留無字封面。原圖尺寸 1448×1086。", "pageSize": "2048x1536", "coverAssets": {"clean": {"id": "after-school-28bbf5c33b04db7476d433a865845a607f39d81eea745d9df37d51bbd59296c3", "name": "cover.png", "asset": "stories/saved/images/28bbf5c33b04db7476d433a865845a607f39d81eea745d9df37d51bbd59296c3.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2602911}, "selected": {"id": "after-school-566f1b794c0eb7395dc49623144a1e5c78959151fce3e368c48958302d112cc8", "name": "cover-titled-A.png", "asset": "stories/saved/images/566f1b794c0eb7395dc49623144a1e5c78959151fce3e368c48958302d112cc8.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2635116}}, "pages": [{"id": "yuyu-after-school-v1-cover", "title": "封面", "text": "", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 86.9, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": false, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-566f1b794c0eb7395dc49623144a1e5c78959151fce3e368c48958302d112cc8", "name": "cover-titled-A.png", "asset": "stories/saved/images/566f1b794c0eb7395dc49623144a1e5c78959151fce3e368c48958302d112cc8.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2635116}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-1", "title": "放學鐘響", "text": "放學鐘響了。\n瑜瑜收好鉛筆盒，把椅子推回桌下。\n「老師再見！」\n下午的陽光照進教室，今天的小冒險正要開始。", "scene": "教室下午中景，瑜瑜整理書包；制服與第一本一致。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-15c89cd7ddbcae265b8438131d590b624385c04bd87f6fb8b4b2fbde0bf6604c", "name": "page01.png", "asset": "stories/saved/images/15c89cd7ddbcae265b8438131d590b624385c04bd87f6fb8b4b2fbde0bf6604c.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2207939}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-2", "title": "校門口道別", "text": "到了校門口，瑜瑜看見媽媽。\n她轉過身，向湘湘揮揮手。\n「明天見！」\n「明天見！」\n兩個朋友，各自走向等候的家人。", "scene": "校門接送區，湘湘雙辮子；瑜瑜媽媽粉桃直條上衣、米色長裙。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-1a1250caff0e4f09d28670dc741878d5948db04a79fdb8e53b93c6edf993a271", "name": "page02.png", "asset": "stories/saved/images/1a1250caff0e4f09d28670dc741878d5948db04a79fdb8e53b93c6edf993a271.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2424697}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-3", "title": "媽媽的小任務", "text": "「家裡需要牛奶和雞蛋。」媽媽說。\n「今天，讓你當採買小幫手，好嗎？」\n她把購物小紙條和零錢交給瑜瑜。\n「我陪你去，你來試著買。」", "scene": "媽媽蹲下交紙條與小零錢包，物品一一可辨；不散落現金，不跨馬路交物。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-d43b79d1d3432524e9c30b79d7af71e6df0d3f8abb16d29f020fbe298bbd2b17", "name": "page03.png", "asset": "stories/saved/images/d43b79d1d3432524e9c30b79d7af71e6df0d3f8abb16d29f020fbe298bbd2b17.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2319100}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-4", "title": "先確認要買什麼", "text": "瑜瑜看著小紙條，念了一遍：\n「牛奶一瓶，雞蛋一盒。」\n她放好書包，把紙條和零錢包收好。\n「買完先回家，再去公園。」\n她和媽媽把順序也說好了。", "scene": "紙條近景，用牛奶瓶與一盒蛋小圖，不讓生成字取代後製清單。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-42ab62cbf9a49de6713123d1136952d551cfddbdf5c60974ae30e6fcf9543cdb", "name": "page04.png", "asset": "stories/saved/images/42ab62cbf9a49de6713123d1136952d551cfddbdf5c60974ae30e6fcf9543cdb.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2431348}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-5", "title": "今天換我帶路", "text": "熟悉的小巷，今天好像有點不一樣。\n「小店在這邊！」瑜瑜說。\n媽媽走在她身旁，讓她認一認路。\n瑜瑜覺得，自己的眼睛比平常更忙了。", "scene": "母女走人行道，家長在孩子靠車道外側，店鋪無品牌文字。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-a111e8f511e7de4b08b55da1ac28b00a041f09f161f5f536d9a5a11bbea2d6cc", "name": "page05-street-v2.png", "asset": "stories/saved/images/a111e8f511e7de4b08b55da1ac28b00a041f09f161f5f536d9a5a11bbea2d6cc.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2723670}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-6", "title": "到了路口先停下", "text": "到了路口，瑜瑜停在線後。\n她牽好媽媽的手，等行人綠燈亮起。\n媽媽和她一起確認兩邊的車都停了，才走斑馬線。\n「不著急，平安到才重要。」", "scene": "只畫等候一個時刻：母女在路緣後，人行紅燈、車行道清楚。絕不同格多個互相衝突號誌。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-ce41b88dcc26c2d41fecd109ab253a2a6ea0fdd379fb5e200ca2d9dc45c8f7ed", "name": "page06.png", "asset": "stories/saved/images/ce41b88dcc26c2d41fecd109ab253a2a6ea0fdd379fb5e200ca2d9dc45c8f7ed.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2679322}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-7", "title": "小店到了", "text": "小店的門打開了。\n「你好！」瑜瑜向店員打招呼。\n媽媽在她旁邊拿起購物籃。\n「今天你來找，我幫你拿籃子。」", "scene": "社區雜貨店入口，兩人一起入店；無品牌招牌。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-d376bf79d58873b29e8f2fbe3d0acc1119c5a77db2ce5e2f19b6824839d2c0b4", "name": "page07.png", "asset": "stories/saved/images/d376bf79d58873b29e8f2fbe3d0acc1119c5a77db2ce5e2f19b6824839d2c0b4.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2245015}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-8", "title": "牛奶找到了", "text": "瑜瑜在冷藏櫃看見牛奶。\n「找到第一樣了！」\n她和媽媽確認要買的那一瓶，把它放進籃子。\n可是，雞蛋在哪裡呢？", "scene": "牛奶從低層冷藏櫃取出，媽媽扶籃；冷藏櫃門正常不穿手。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-b1537d0c4cc66a333b3265239f2e114fc0266cc4bee8f85bb6bb1bcf76769f3a", "name": "page08.png", "asset": "stories/saved/images/b1537d0c4cc66a333b3265239f2e114fc0266cc4bee8f85bb6bb1bcf76769f3a.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2366513}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-9", "title": "請問雞蛋在哪裡", "text": "瑜瑜看看媽媽，又看看店員。\n她鼓起勇氣說：\n「請問，雞蛋在哪裡？」\n店員指向旁邊的架子。\n原來，不知道的時候，可以好好開口問。", "scene": "孩子面向櫃台店員提問，媽媽一旁鼓勵；不安排跟陌生人去隱蔽處。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-692dd8d6df0bbf5bc600bdd0fa8ff7621a8217a12b27c3100e71c58c37a23f4d", "name": "page09.png", "asset": "stories/saved/images/692dd8d6df0bbf5bc600bdd0fa8ff7621a8217a12b27c3100e71c58c37a23f4d.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2402528}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-10", "title": "我來付錢", "text": "瑜瑜把牛奶和雞蛋放到櫃台。\n她拿出零錢，請媽媽陪她一起核對。\n「謝謝！」\n收好找零和收據，她仔細拉上零錢包。\n小任務，完成了！", "scene": "櫃台俯視，蛋盒蓋好，牛奶一瓶；錢在托盤，不用可讀價格與錯誤算式。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-281baaf3cc8d87ad9048d94a3801fc7c0b119824ac2d6197452d4ed1b30e76ce", "name": "page10.png", "asset": "stories/saved/images/281baaf3cc8d87ad9048d94a3801fc7c0b119824ac2d6197452d4ed1b30e76ce.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2301961}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-11", "title": "先送食材回家", "text": "回家的路上，媽媽提著購物袋，瑜瑜走在旁邊。\n「雞蛋不能碰撞，牛奶也要先放好。」\n到家後，她幫忙把東西交給媽媽，放進冰箱。\n現在，可以安心去公園了。", "scene": "只畫到家廚房交接食材時刻；媽媽處理冷藏，瑜瑜站地面不攀高。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-439d8d8f8445af61f0b4ef84d39f2c770f5b5d76f9b777b818d2da086b99e764", "name": "page11.png", "asset": "stories/saved/images/439d8d8f8445af61f0b4ef84d39f2c770f5b5d76f9b777b818d2da086b99e764.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2022903}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-12", "title": "公園的小約定", "text": "洗好手，喝口水，母女倆又出了門。\n公園就在家附近。\n「我們走一小圈，晚餐前回家。」媽媽說。\n「我會待在你看得到的地方！」瑜瑜答應。", "scene": "公園入口，孩子已無書包、無購物袋；媽媽一起，仍有日光。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-167137a10b055384905fa7f069f05fe27a37dfda4e75f6ac04b63a216627ac9f", "name": "page12.png", "asset": "stories/saved/images/167137a10b055384905fa7f069f05fe27a37dfda4e75f6ac04b63a216627ac9f.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2869154}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-13", "title": "準備好再探索", "text": "到了長椅旁，瑜瑜停下腳步。\n她檢查鞋帶，媽媽幫忙把鬆開的地方綁好。\n「準備好了！」\n這次，她不用擔心碰破雞蛋，可以慢慢看、慢慢找。", "scene": "媽媽單膝蹲繫鞋帶，孩子坐穩長椅；無購物食材，水瓶媽媽持有或包內。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-8aa18d487db4b970e446ae03109d4f56484f913f983934e27598751fcdc88ca0", "name": "page13.png", "asset": "stories/saved/images/8aa18d487db4b970e446ae03109d4f56484f913f983934e27598751fcdc88ca0.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2690104}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-14", "title": "地面的小世界", "text": "一片葉子躺在小路旁。\n葉子附近，有慢慢爬的蝸牛，也有忙忙碌碌的螞蟻。\n瑜瑜蹲下來看。\n她不踩、不抓，只用眼睛跟著牠們走。", "scene": "低機位孩子觀察落葉和小蝸牛，螞蟻細小比例正常；媽媽在近處，不觸碰野生生物。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-32a6b572b72363e1b29cad4a78382be6b1d0e1da0053872efca0aa507eb9bc29", "name": "page14.png", "asset": "stories/saved/images/32a6b572b72363e1b29cad4a78382be6b1d0e1da0053872efca0aa507eb9bc29.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2587176}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-15", "title": "安靜的小觀眾", "text": "矮樹枝上，停著一隻小鳥。\n瑜瑜本來想叫媽媽，馬上又放輕聲音。\n「你看……」\n母女倆留在原地，安靜地看。\n小鳥抖抖羽毛，唱了兩聲。", "scene": "母女與鳥保持距離，不靠近鳥巢，不餵食；枝上正常小鳥，不巨大化。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-01943531e3e3c43a20c7a6304c1f58694fdcb2f7e79c695e1fbaa69a1e31ac25", "name": "page15.png", "asset": "stories/saved/images/01943531e3e3c43a20c7a6304c1f58694fdcb2f7e79c695e1fbaa69a1e31ac25.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2673565}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-16", "title": "還想再看一下", "text": "瑜瑜看得入迷，還想再找一隻蝸牛。\n這時，媽媽輕聲提醒：「快到約好的時間了。」\n瑜瑜看看天色。\n「啊，我差點忘記！」\n好玩的事，也要記得時間。", "scene": "媽媽指自己的手錶、瑜瑜抬頭；夕陽仍明亮，不已天黑才想回去。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-f7f75c002e707c0c1cb631414e3caf3db37e163b5423effcaeee2268bf1ae739", "name": "page16-watch-v2.png", "asset": "stories/saved/images/f7f75c002e707c0c1cb631414e3caf3db37e163b5423effcaeee2268bf1ae739.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2739074}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-17", "title": "我們回家吧", "text": "瑜瑜在地上挑了一片乾淨的落葉，先問媽媽能不能帶回家。\n她沒有摘樹上的葉子，也沒有帶走小動物。\n「明天再來看你們！」\n她牽著媽媽，沿著熟悉的路回家。", "scene": "母女在公園出口，孩子拿一片落葉，另一手牽媽媽；夕陽不夜行。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-982707d06e9e272af5c13b7e640c7eba9ace5c7b3b8052be0605b1a84f314acb", "name": "page17.png", "asset": "stories/saved/images/982707d06e9e272af5c13b7e640c7eba9ace5c7b3b8052be0605b1a84f314acb.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2732445}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-18", "title": "平平安安到家", "text": "家門打開，爸爸探出頭來。\n「今天的小探險，順利嗎？」\n「順利！」瑜瑜說。\n她把葉子先放好，換鞋、洗手。\n再等一下，她有好多故事要說。", "scene": "家門迎接單一時刻，爸爸固定淺藍襯衫白T卡其褲；不要同格又洗手又開門。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-e8dea8d3c8dccca3e5e3876679f5f07a74d3b190db675aba87488f04b482a37a", "name": "page18.png", "asset": "stories/saved/images/e8dea8d3c8dccca3e5e3876679f5f07a74d3b190db675aba87488f04b482a37a.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2130744}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-19", "title": "今天我做到了", "text": "晚餐前，瑜瑜一件一件說給爸爸聽。\n「我自己問店員，也試著付錢！」\n「公園有蝸牛，還有一隻小鳥。」\n她想了想，又說：「我差點忘記時間。下次，我也要記得看看。」", "scene": "餐桌前全家分享，妈妈開眼溫柔聽，爸爸驚喜；橘皮小貓可在旁邊椅子，不上餐盤。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 74.6, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-d54a6e8f07a36a2a8d6d305031fd465b10f4c00ca4b5094ca0b159a0c876ced6", "name": "page19.png", "asset": "stories/saved/images/d54a6e8f07a36a2a8d6d305031fd465b10f4c00ca4b5094ca0b159a0c876ced6.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2188884}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-after-school-v1-page-20", "title": "家附近的小冒險", "text": "晚上，瑜瑜把落葉收進小盒子。\n橘皮小貓靠在枕頭旁，像也在聽今天的故事。\n原來，冒險不一定要去很遠。\n家旁的小路、小店和公園，就有好多新發現。\n最重要的是，平平安安回家，把故事說給最愛的人聽。", "scene": "臥室睡前粉色兔子睡衣，橘皮玩偶固定黑白臉黃眼綠葉，開盒放葉；其他頁不把玩偶活化。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "after-school-9a673c603e609837ed5daebb0f6d32bddf22bda21102afa30ca60fb0678bbe3d", "name": "page20.png", "asset": "stories/saved/images/9a673c603e609837ed5daebb0f6d32bddf22bda21102afa30ca60fb0678bbe3d.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2022034}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}]}, {"id": "yuyu-try-again-v1", "title": "我可以再試一次", "overview": "挫折→休息→找原因→拆開練習→換方法→發現自己的進步\n20 頁正文，封面另計。正文文字可獨立編輯與拖曳。A 版封面的書名已印在圖片上；另保留無字封面。原圖尺寸 1448×1086。", "pageSize": "2048x1536", "coverAssets": {"clean": {"id": "try-again-31ee3cb05762ff076833e8bd49a4a3b87d428ddf0a88d5fb9109f99ea7d0f73f", "name": "cover.png", "asset": "stories/saved/images/31ee3cb05762ff076833e8bd49a4a3b87d428ddf0a88d5fb9109f99ea7d0f73f.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2409891}, "selected": {"id": "try-again-cff89be9bf60e0683215854aae5aa5233d5481f883d8aa034923d6131635787d", "name": "cover-titled-A.png", "asset": "stories/saved/images/cff89be9bf60e0683215854aae5aa5233d5481f883d8aa034923d6131635787d.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2437863}}, "pages": [{"id": "yuyu-try-again-v1-cover", "title": "封面", "text": "", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 86.9, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": false, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-cff89be9bf60e0683215854aae5aa5233d5481f883d8aa034923d6131635787d", "name": "cover-titled-A.png", "asset": "stories/saved/images/cff89be9bf60e0683215854aae5aa5233d5481f883d8aa034923d6131635787d.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2437863}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-1", "title": "我也想做到", "text": "公園裡，\n有人一下、兩下、三下，\n跳得又快又輕。\n\n瑜瑜看得眼睛亮亮的。\n「我也想學會！」", "scene": "公園平坦空地，瑜瑜在安全距離外看別人跳繩；媽媽在旁，繩圈與旁人不重疊。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 66.4, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-601d3b31c972db8db9b4c66e6f4386752f0c3cf307e6077d916df7eb245f6925", "name": "page01.png", "asset": "stories/saved/images/601d3b31c972db8db9b4c66e6f4386752f0c3cf307e6077d916df7eb245f6925.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2425592}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-2", "title": "第一次開始", "text": "瑜瑜把跳繩拿好，\n雙腳站得穩穩的。\n\n「好，開始！」\n她把繩子轉過頭頂。", "scene": "全身側前景，兩手各一握把，繩子唯一連續路徑呈頭頂弧；運動鞋鞋帶綁好。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 70.5, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-55b63814562ca1b8011e6f81efaa192fc145cfe30e23be57523056e6ec99eb13", "name": "page02.png", "asset": "stories/saved/images/55b63814562ca1b8011e6f81efaa192fc145cfe30e23be57523056e6ec99eb13.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2510727}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-3", "title": "啪！", "text": "啪！\n\n繩子碰到鞋子前面，\n瑜瑜沒有跳過去。\n\n「咦？」\n她站穩，低頭看看繩子。", "scene": "跳完已停，繩鬆落鞋尖前，不纏住腳踝、不摔倒；不畫多條運動殘影。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-8963dd2952b1f69283bbbd1b5527a6c2c8983eea5f4ad15679f8a43af3155102", "name": "page03.png", "asset": "stories/saved/images/8963dd2952b1f69283bbbd1b5527a6c2c8983eea5f4ad15679f8a43af3155102.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2426690}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-4", "title": "再來一次", "text": "「剛剛只是沒準備好。」\n\n瑜瑜又試了一次。\n這一次——\n啪！\n\n繩子又碰到鞋子了。", "scene": "同一場所第二次停住的反應中景；兩手握把，繩落地正常，臉開始不解。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-8fc298fbdc26985c23ddf1dc092edd345560352b3cafd7c116f1c375bbdd14d1", "name": "page04.png", "asset": "stories/saved/images/8fc298fbdc26985c23ddf1dc092edd345560352b3cafd7c116f1c375bbdd14d1.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2589591}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-5", "title": "為什麼別人可以？", "text": "旁邊的小朋友\n一下、一下、一下，\n跳個不停。\n\n瑜瑜看看他們，\n再看看自己。\n\n「為什麼大家都會，\n只有我不會？」", "scene": "瑜瑜失落近景，遠處一個孩子跳繩，別人不嘲笑她。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 54.1, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-36e80ff5a024bcd9f724121f6a285afefab4eab230298bab5bec968d2ed70612", "name": "page05.png", "asset": "stories/saved/images/36e80ff5a024bcd9f724121f6a285afefab4eab230298bab5bec968d2ed70612.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2525635}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-6", "title": "越急越亂", "text": "她把繩子轉得更快，\n也跳得更高。\n\n可是越急，\n手和腳越配合不起來。\n\n才轉一下，\n她又停住了。", "scene": "只呈現急促後停下時刻，眉皺肩緊；不示範繩纏腳、纏頸或甩向旁人。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-15272de8a5ea4f402dd9a5caef667d5a989ee37200408afdb654d38cf406ba87", "name": "page06.png", "asset": "stories/saved/images/15272de8a5ea4f402dd9a5caef667d5a989ee37200408afdb654d38cf406ba87.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2398306}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-7", "title": "我不要學了！", "text": "「我不要學了！」\n\n瑜瑜把跳繩放到一旁。\n她的臉紅紅的，\n眼睛也酸酸的。\n\n「我就是不會。」", "scene": "瑜瑜坐長椅生氣，跳繩整條放一旁，不投擲；表情不污名化。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-58e42f275b803f28f82886f38bc6051aa0bf03861f6f4f3afd9647bf441673e5", "name": "page07.png", "asset": "stories/saved/images/58e42f275b803f28f82886f38bc6051aa0bf03861f6f4f3afd9647bf441673e5.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2601873}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-8", "title": "先休息一下", "text": "媽媽沒有馬上說話。\n\n她只是坐到瑜瑜旁邊。\n\n風吹過樹葉，\n兩個人安靜了一會兒。", "scene": "母女並坐，媽媽不指責、不拉扯；一張完整安靜畫面。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 66.4, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-9fc0a53e51ab1d8c0569c8766987b03a0340de53478298455b0ac56c76c7ea0d", "name": "page08.png", "asset": "stories/saved/images/9fc0a53e51ab1d8c0569c8766987b03a0340de53478298455b0ac56c76c7ea0d.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2540929}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-9", "title": "大人也會失敗", "text": "過了一會兒，\n媽媽輕輕說：\n\n「你知道嗎？\n媽媽以前學游泳，\n也練了好多次才學會。」\n\n瑜瑜抬起頭。\n「真的嗎？」", "scene": "只畫母女分享近景，不用同頁游泳回憶拼貼；媽媽自然小笑，瑜瑜好奇。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 54.1, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-d9e6d334bc16a634a9cdf0e9780dc9f57c74a6568b919e69b2d8e7efd5e53558", "name": "page09.png", "asset": "stories/saved/images/d9e6d334bc16a634a9cdf0e9780dc9f57c74a6568b919e69b2d8e7efd5e53558.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2467934}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-10", "title": "不是不會，是還沒會", "text": "媽媽說：\n\n「現在不會，\n不代表永遠不會。」\n\n「我們不要一直急著跳，\n先看看是哪裡卡住了。」", "scene": "母女看平放的繩子與握把，媽媽蹲下平視，不示範危險纏繞。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-2f5ea806225274d75413f51af235a6a226fddf111178f31c3ba2e8bd4721d46e", "name": "page10.png", "asset": "stories/saved/images/2f5ea806225274d75413f51af235a6a226fddf111178f31c3ba2e8bd4721d46e.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2571203}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-11", "title": "先只練手", "text": "她們先把繩子放下，\n不急著跳。\n\n瑜瑜空著手，\n練習手腕小小地轉圈。\n\n「原來不用甩得那麼大！」", "scene": "空手站立模擬握把，手在身體兩側小幅轉動；繩收在長椅，不在身旁旋轉撞人。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-d42e5c202b2798c9a803cb2aabff75a72c499e5ac67e737f4ae719a6d3535c79", "name": "page11.png", "asset": "stories/saved/images/d42e5c202b2798c9a803cb2aabff75a72c499e5ac67e737f4ae719a6d3535c79.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2530723}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-12", "title": "再只練腳", "text": "接著，\n她只練小小地跳。\n\n一下。\n一下。\n一下。\n\n「不用跳那麼高耶！」", "scene": "一個小跳瞬間，雙腳僅稍離地，膝蓋放鬆；不畫同人三分身或三對腿。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-d4aabd928adb0decacd63c25b071ee3556abf36418145d573794b6b74a2c0e2a", "name": "page12.png", "asset": "stories/saved/images/d4aabd928adb0decacd63c25b071ee3556abf36418145d573794b6b74a2c0e2a.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2417490}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-13", "title": "合起來試試看", "text": "瑜瑜重新拿起跳繩。\n\n轉——\n跳！\n\n繩子第一次\n從她腳下完整地過去了。\n\n「我跳過去了！」", "scene": "側視單一繩通過腳底的瞬間，兩握把、一條繩，繩不可穿鞋穿腿；不合理就改成功後反應。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 54.1, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-6f2d31c7f4deae905bcd224d4b68873b83382180d2040df900465ce2475e6b9b", "name": "page13.png", "asset": "stories/saved/images/6f2d31c7f4deae905bcd224d4b68873b83382180d2040df900465ce2475e6b9b.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2469998}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-14", "title": "又停住了", "text": "可是第二下，\n繩子又碰到鞋子。\n\n瑜瑜停下來。\n\n這一次，\n她沒有把繩子放棄在一旁。", "scene": "成功一次後再停住，仍握繩、表情思考不是笑；繩鬆落無打結。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-442151ae3c71bf767f85b009049f5b8c813b7148bf80067a8a0efecb6360dec9", "name": "page14.png", "asset": "stories/saved/images/442151ae3c71bf767f85b009049f5b8c813b7148bf80067a8a0efecb6360dec9.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2362979}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-15", "title": "我想再看看", "text": "瑜瑜想了一下。\n\n「我剛剛是不是跳太早了？」\n\n媽媽說：「有可能，\n我們慢慢試一次，看看。」\n\n這一次，\n她開始留意自己的動作。", "scene": "母女討論近景；不以媽媽點頭當未驗證猜測的定論。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 54.1, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-67f08c3f6e8c8ba1e0961a6b4252beed39281e7bab42c600f4d97f49febe869c", "name": "page15.png", "asset": "stories/saved/images/67f08c3f6e8c8ba1e0961a6b4252beed39281e7bab42c600f4d97f49febe869c.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2377878}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-16", "title": "換一個方法", "text": "這時，爸爸也來到公園。\n他站在繩圈外，幫她拍節奏。\n\n「轉——跳！」\n「轉——跳！」\n\n瑜瑜跟著節奏，\n慢慢找到感覺。", "scene": "爸爸首次入場固定藍襯衫白T卡其褲，繩圈外拍手；兩隻手正常。媽媽近旁。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-c922efd11494f66301608105d116435fbc566ce89d57a8618679cb99257fb32f", "name": "page16.png", "asset": "stories/saved/images/c922efd11494f66301608105d116435fbc566ce89d57a8618679cb99257fb32f.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2607731}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-17", "title": "一、二、三", "text": "一下。\n兩下。\n三下。\n\n瑜瑜停下來，\n自己都嚇了一跳。\n\n「三下！」", "scene": "跳完停穩驚喜近景，媽媽豎三指可改微笑避免錯指；不在圖上生成計數字。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-afa63bb9b4f2f3135da612316e6d79ab51c7c945fa481966a90735cca2a26042", "name": "page17.png", "asset": "stories/saved/images/afa63bb9b4f2f3135da612316e6d79ab51c7c945fa481966a90735cca2a26042.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2514089}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-18", "title": "慢慢多一點", "text": "第二天，她試著跳了五下。\n再過一天，她跳了八下。\n\n有時候還是會卡住，\n有時候也比前一天少。\n\n可是瑜瑜知道，\n休息一下，還能再練習。", "scene": "只畫第三天一次練習，同人物服裝允許洗換但核心髮夾不變；日期用後製，不畫三人分身蒙太奇。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-18e13c67375f67a266f33b9554cd9f80363b80c4bf0bdb376ba7bf78705751c6", "name": "page18.png", "asset": "stories/saved/images/18e13c67375f67a266f33b9554cd9f80363b80c4bf0bdb376ba7bf78705751c6.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2477317}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-19", "title": "我不用跟別人一樣", "text": "旁邊有人跳了二十下。\n瑜瑜跳了十下。\n\n她也笑得好開心。\n因為她知道——\n\n她已經找到\n更適合自己的方法。", "scene": "孩子跳完後開心看媽媽，其他孩子遠景；不畫排行榜或比較獎牌。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-6e95c587bead71acbf505823fe58fb3e27d51b67ed11a43be5056f3b8956051e", "name": "page19.png", "asset": "stories/saved/images/6e95c587bead71acbf505823fe58fb3e27d51b67ed11a43be5056f3b8956051e.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2555597}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-try-again-v1-page-20", "title": "我可以再試一次", "text": "原來，\n勇敢不是一次就成功。\n\n是遇到困難的時候，\n願意停一下、想一想。\n\n然後告訴自己：\n\n「沒關係，\n我可以再試一次。」", "scene": "夕陽母女收繩，瑜瑜穩重滿足，橘皮小貓可作媽媽袋外小吊飾但不擅改玩偶尺寸：本頁不放，保持同一完整玩偶留家中。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 50.0, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "try-again-6a586a97c6609a7843c0b47504ed56e0cd18002802ce1f79216d42009d533831", "name": "page20.png", "asset": "stories/saved/images/6a586a97c6609a7843c0b47504ed56e0cd18002802ce1f79216d42009d533831.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2470625}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}]}, {"id": "yuyu-why-v1", "title": "為什麼？", "overview": "提問→猜測→公平比較→觀察證據→新問題；凝結為貫穿主線\n20 頁正文，封面另計。正文文字可獨立編輯與拖曳。A 版封面的書名已印在圖片上；另保留無字封面。原圖尺寸 1448×1086。", "pageSize": "2048x1536", "coverAssets": {"clean": {"id": "why-b3daf4eded7a097105ab69044bffcb8e51ae7871df65f8dbd770c349aa8570e6", "name": "cover.png", "asset": "stories/saved/images/b3daf4eded7a097105ab69044bffcb8e51ae7871df65f8dbd770c349aa8570e6.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2047946}, "selected": {"id": "why-bc07b3c4b7ec076b56a54042fe628a932ec8f6f7ede9cf4a2dbd7823dc860d27", "name": "cover-titled-A.png", "asset": "stories/saved/images/bc07b3c4b7ec076b56a54042fe628a932ec8f6f7ede9cf4a2dbd7823dc860d27.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2157413}}, "pages": [{"id": "yuyu-why-v1-cover", "title": "封面", "text": "", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 86.9, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": false, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-bc07b3c4b7ec076b56a54042fe628a932ec8f6f7ede9cf4a2dbd7823dc860d27", "name": "cover-titled-A.png", "asset": "stories/saved/images/bc07b3c4b7ec076b56a54042fe628a932ec8f6f7ede9cf4a2dbd7823dc860d27.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2157413}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-1", "title": "窗戶為什麼會流汗？", "text": "早上起床，\n瑜瑜發現窗戶上\n有一顆一顆的小水珠。\n\n「咦？」\n「窗戶為什麼會流汗？」", "scene": "偏涼清晨，窗玻璃內側凝露、室內溫暖；瑜瑜粉色睡衣站地面，不爬窗臺。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 66.4, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-a662d29a84b370e7da3182edb24395bf9e8363f7fe04ab49053b3bb3b0627d6c", "name": "page01.png", "asset": "stories/saved/images/a662d29a84b370e7da3182edb24395bf9e8363f7fe04ab49053b3bb3b0627d6c.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2350516}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-2", "title": "可可粉去哪裡了？", "text": "吃早餐時，\n瑜瑜把可可粉加進牛奶裡。\n\n攪一攪，\n牛奶變成了棕色，\n小粉粒不像剛才那麼容易看見。\n\n「它們跑去哪裡了？」", "scene": "杯中棕色牛奶、有微小粉粒，不做粉消失魔法。媽媽旁看，冷或溫飲非滾燙。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-5fb98be4845cebbed8ede52e4d101f9eb63048a9b54906666ebae44448e4939a", "name": "page02.png", "asset": "stories/saved/images/5fb98be4845cebbed8ede52e4d101f9eb63048a9b54906666ebae44448e4939a.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2167298}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-3", "title": "影子怎麼變長了？", "text": "走在上學路上，\n瑜瑜看看自己的影子。\n\n今天早上的影子長長的，\n和她記得中午看到的不一樣。\n\n「為什麼影子會變？」", "scene": "低太陽清晨長影，一個人一個同向投影，母女光源一致；不畫同一刻忽長忽短。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-62490f6bc6001d8b5a29935d970487a77f6a50fa27ec63cbe552f481ef62e646", "name": "page03.png", "asset": "stories/saved/images/62490f6bc6001d8b5a29935d970487a77f6a50fa27ec63cbe552f481ef62e646.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2585948}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-4", "title": "磁鐵為什麼不會掉？", "text": "到了教室，\n老師把大磁鐵放在黑板上。\n\n它沒有掉下來。\n\n瑜瑜馬上舉手：\n「為什麼？」", "scene": "老師使用大型教具磁鐵於可吸附鐵質黑板，無可吞小磁珠，其他物件不全被吸。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-2fdf8465484716cce459b64d5c3e4fcf2e90f45ccd8e7e8803bc131d96144c4f", "name": "page04.png", "asset": "stories/saved/images/2fdf8465484716cce459b64d5c3e4fcf2e90f45ccd8e7e8803bc131d96144c4f.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2107261}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-5", "title": "植物為什麼朝著窗戶？", "text": "窗邊的一盆小苗，\n莖和葉子朝著亮亮的地方伸去。\n\n瑜瑜歪著頭。\n\n「它也喜歡看窗外嗎？」", "scene": "單盆小苗輕微向窗光，不說所有植物都偏斜；無擬人眼睛。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 66.4, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-95f31e18ffe403396f2f42231138d7f511c62bfff69c45f3cc1b6b84b3bc07e5", "name": "page05.png", "asset": "stories/saved/images/95f31e18ffe403396f2f42231138d7f511c62bfff69c45f3cc1b6b84b3bc07e5.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2176693}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-6", "title": "雲裡面裝了什麼？", "text": "下午，\n天空變得灰灰的。\n\n雨滴答、滴答落下來。\n\n「雲裡面到底裝了什麼？」", "scene": "教室窗內看雨，無暴雨外出；正常雨雲無裝水桶卡通。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 66.4, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-12dbb495b5e3e8f633e2b48ba10acf9383f49daded26d0568311bde4289729c8", "name": "page06.png", "asset": "stories/saved/images/12dbb495b5e3e8f633e2b48ba10acf9383f49daded26d0568311bde4289729c8.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2179175}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-7", "title": "杯子為什麼會唱歌？", "text": "探索活動時，\n老師輕輕敲了幾個裝水的杯子。\n\n叮。\n噹。\n咚。\n\n「為什麼聲音不一樣？」", "scene": "成人敲杯，三個同款同尺寸玻璃杯不同水量，放防滑托盤；小朋友手不碰杯。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-5cc3f2040b1e58b1702f76eb0e97068ad3cc459480c45cb075ca7e2056ee4274", "name": "page07.png", "asset": "stories/saved/images/5cc3f2040b1e58b1702f76eb0e97068ad3cc459480c45cb075ca7e2056ee4274.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2289510}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-8", "title": "老師沒有直接告訴我", "text": "瑜瑜以為老師會直接回答。\n\n沒想到老師笑著說：\n「你覺得呢？」\n\n瑜瑜愣了一下。\n她也可以先想一想嗎？", "scene": "老師與瑜瑜平視對話，桌上沿用三同款杯，畫面不生文字。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-da5dea5738a83f6bb200afb54f760fe8fda6e78838fdd000dcd1b9da5a784e2f", "name": "page08.png", "asset": "stories/saved/images/da5dea5738a83f6bb200afb54f760fe8fda6e78838fdd000dcd1b9da5a784e2f.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2178176}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-9", "title": "先猜一猜", "text": "有人說：\n「是不是杯子不一樣？」\n\n有人說：\n「是不是水在唱歌？」\n\n瑜瑜也舉手：\n「是不是水越多，聲音越低？」", "scene": "學生輪流發言一時刻，瑜瑜舉一手；猜測不以大勾號當答案。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-47bb970d8b63ffa64d22185401687c43393e8181f2b6b4e3d0565dc857b9d320", "name": "page09.png", "asset": "stories/saved/images/47bb970d8b63ffa64d22185401687c43393e8181f2b6b4e3d0565dc857b9d320.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2259387}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-10", "title": "猜了以後，要找證據", "text": "老師說：「我們來比較看看。」\n\n杯子用同一種，\n敲的位置和力道也盡量相同，\n只改變水量。\n\n大家仔細聽，再記下來。\n這次輕敲時，水較多的杯子，\n聽起來比較低。", "scene": "同款三杯，少中多水可辨，老師同工具輕敲，孩子圖畫記錄；不畫吹瓶，區別吹氣音高。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 54.1, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-21543f9f4975aca4e9c6195fb9a4979b91b3cfa357a8f57da39ec563b1d01515", "name": "page10.png", "asset": "stories/saved/images/21543f9f4975aca4e9c6195fb9a4979b91b3cfa357a8f57da39ec563b1d01515.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2320009}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-11", "title": "窗戶流汗的秘密", "text": "接著，老師拿來兩個一樣的透明杯。\n一杯裝常溫水，一杯裝冰水，\n先把杯子外面擦乾。\n\n過了一會兒，\n冰水杯外面冒出小水珠。\n\n「咦？跟早上的窗戶好像！」", "scene": "兩透明塑膠杯同型，冰杯有外水珠、常溫杯乾；均無熱水，老師在旁。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-174cd5f7b065bf96a430963ae8188f5ddbf83375773433e1f5ea9e02b44de645", "name": "page11.png", "asset": "stories/saved/images/174cd5f7b065bf96a430963ae8188f5ddbf83375773433e1f5ea9e02b44de645.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2286783}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-12", "title": "原來不是窗戶在流汗", "text": "老師說：\n「空氣裡有看不見的水蒸氣。」\n\n「碰到夠冷的表面，\n就可能凝結成小水珠。」\n\n瑜瑜睜大眼睛。\n「原來不是杯子漏水呀！」", "scene": "杯外凝結近景與孩子反應，水珠不從杯內穿壁；不把氣體畫水滴假裝可見。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-2234c9b72b3522db88fa5ea84f1f12037250d3880e729d265910f79bf0cc65dd", "name": "page12.png", "asset": "stories/saved/images/2234c9b72b3522db88fa5ea84f1f12037250d3880e729d265910f79bf0cc65dd.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2231712}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-13", "title": "那雲呢？", "text": "她才剛知道一件事，\n馬上又想到另一個問題。\n\n「那雲呢？也跟水有關嗎？」\n\n老師說：「對呀，雲裡有好多小水滴，\n有些雲裡還有小冰晶。」\n\n瑜瑜又想問：\n「那它們怎麼變成雨呢？」", "scene": "雨後窗前雲景，老師指自然雲；微觀圖如需另做經驗證素材，不硬生成冰滴比例。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 50.0, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-fd13e114ce5ee1624ecced2bab28b4854f8d0f4609930ab5a4a389eb1e9b280e", "name": "page13.png", "asset": "stories/saved/images/fd13e114ce5ee1624ecced2bab28b4854f8d0f4609930ab5a4a389eb1e9b280e.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2244251}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-14", "title": "鍋蓋上的小水滴", "text": "晚上，爸爸正在煮湯。\n他用隔熱手套拿起鍋蓋，\n讓瑜瑜站在安全的地方看。\n\n「爸爸！蓋子裡有小水滴！」\n\n「這個是不是也跟窗戶一樣？」", "scene": "爸爸掌控熱鍋蓋、戴手套、蒸氣遠離孩子，孩子遠離爐台不伸手，鍋蓋滴水非漏。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 62.300000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-eedabd0816968f2f1d20bb11e198868dd7238715af05c7e08addb4db8a0d549b", "name": "page14.png", "asset": "stories/saved/images/eedabd0816968f2f1d20bb11e198868dd7238715af05c7e08addb4db8a0d549b.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2249909}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-15", "title": "爸爸也不急著說答案", "text": "爸爸說：\n「這兩件事很像，我們再比一比。」\n\n等離開爐台，\n他拿出兩個一樣的杯子。\n\n「一杯常溫水，一杯冰水，\n你猜哪個杯子外面會先有水珠？」", "scene": "改在餐桌安全冰水對照，爸爸不是叫孩子摸熱鍋蓋；兩同款杯無熱源。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-12e3ac124917468773034126c69d041a2bc47ff027cc0875d444f901ec649409", "name": "page15.png", "asset": "stories/saved/images/12e3ac124917468773034126c69d041a2bc47ff027cc0875d444f901ec649409.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2304249}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-16", "title": "家裡也可以做探索", "text": "原來，\n家裡也有好多問題。\n\n為什麼風扇會讓人覺得涼？\n為什麼冰塊會融化？\n為什麼肥皂泡會有彩虹？\n為什麼植物要澆水？\n\n瑜瑜先記下來，\n再和爸爸媽媽一起選一個來探索。", "scene": "單一全景桌前寫問題本，背景盆栽、封閉扇罩風扇；不畫同格四個實驗，不讓水近插座。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 50.0, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-3ad779ecb90b6fb718ed6119218709d0438005ae1a20f944a8eae924d673ffe0", "name": "page16.png", "asset": "stories/saved/images/3ad779ecb90b6fb718ed6119218709d0438005ae1a20f944a8eae924d673ffe0.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2225979}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-17", "title": "答案可以有很多種找法", "text": "有些問題可以做實驗。\n有些可以看書。\n有些要問老師。\n有些要等一等，\n再仔細觀察。\n\n瑜瑜發現，\n找答案也有好多條路。", "scene": "圖書館母女閱讀一本自然書，保留單景，平板若出現不假造知識文字。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-04889aae1f72a957e098e475fb8d9d1f0746127bdc7f904b20087c1d993695da", "name": "page17.png", "asset": "stories/saved/images/04889aae1f72a957e098e475fb8d9d1f0746127bdc7f904b20087c1d993695da.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2390865}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-18", "title": "有些問題還不知道", "text": "隔天，瑜瑜問：\n「學校的樹，為什麼這幾天落了好多葉子？」\n\n老師想了想。\n「這一棵樹的原因，\n老師現在還不能確定。」\n\n瑜瑜有點驚訝。", "scene": "第二天校園觀樹，正常落葉非必然枯死，老師思考不是無知尷尬，孩子安全樹下。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 58.2, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-108126550ac5cabad21ab1a6bfced7bf908bdddce147292bee4c91a47c5de4dc", "name": "page18.png", "asset": "stories/saved/images/108126550ac5cabad21ab1a6bfced7bf908bdddce147292bee4c91a47c5de4dc.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2617966}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-19", "title": "不知道也可以", "text": "老師拿出一本小冊子。\n\n「不知道，不代表不能問。」\n「我們先記下來，\n看看天氣、找找樹的資料，\n再一起觀察幾天。」\n\n瑜瑜認真地寫下問題。\n還沒找到答案，也有下一步。", "scene": "問題小冊子可空白留後製標題，孩子寫筆正常；老師同前頁角色造型。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 54.1, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-4a584a42eb14c28a7b83285d1e176b9067fcc9730bfd9c1088f4d9ce73e93ed6", "name": "page19.png", "asset": "stories/saved/images/4a584a42eb14c28a7b83285d1e176b9067fcc9730bfd9c1088f4d9ce73e93ed6.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2247986}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}, {"id": "yuyu-why-v1-page-20", "title": "世界還有好多門", "text": "晚上，\n瑜瑜看著窗外的月亮。\n\n今天的月亮，\n不是圓圓的。\n\n「為什麼月亮每天看起來不一樣？」\n媽媽笑著坐到她旁邊。\n\n每一個「為什麼」，\n都像一扇小小的門。\n推開它，世界就又大了一點。", "scene": "粉兔睡衣瑜瑜與媽媽在關窗旁，一個上弦月天空，不畫多月同時；橘皮小貓固定玩偶在枕頭。", "style": {"font": "sans", "color": "#233342", "size": 26, "x": 5, "y": 41.800000000000004, "width": 90, "lineHeight": 1.4, "paragraphGap": 0, "align": "left", "backdrop": true, "showText": true, "boxColor": "#ffffff", "boxOpacity": 65, "borderColor": "#233342", "borderWidth": 0, "rotation": 0, "height": 0}, "image": {"id": "why-432650d935386c80a62b1ef4c18dde94927cc8ca6bd3f714136e50665cf8a040", "name": "page20.png", "asset": "stories/saved/images/432650d935386c80a62b1ef4c18dde94927cc8ca6bd3f714136e50665cf8a040.png", "width": 1448, "height": 1086, "type": "image/png", "size": 2284062}, "fit": "contain", "layers": [], "layerOrder": ["base"], "bundledImageVersion": 1}]}]);
